import pandas as pd
from datetime import datetime
import re

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    raw_payments = inputs["raw_payments"].copy()

    # Initialize reject tracking
    rejects = []
    valid_rows = []

    for idx, row in raw_payments.iterrows():
        row_num = row["row_num"]
        payment_id = row["payment_id"]
        account_id = row["account_id"]
        amount_txt = row["amount_txt"]
        currency = row["currency"]
        pay_date_txt = row["pay_date_txt"]

        reject_reason = None

        # R1: MISSING_ID
        if reject_reason is None:
            if pd.isna(payment_id) or (isinstance(payment_id, str) and payment_id.strip() == ""):
                reject_reason = "MISSING_ID"

        # R2: BAD_AMOUNT
        if reject_reason is None:
            if pd.isna(amount_txt):
                reject_reason = "BAD_AMOUNT"
            else:
                amount_trimmed = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
                if not is_legacy_number(amount_trimmed):
                    reject_reason = "BAD_AMOUNT"

        # R3: NON_POSITIVE
        if reject_reason is None:
            amount_trimmed = amount_txt.strip() if isinstance(amount_txt, str) else str(amount_txt)
            parsed_amount = parse_legacy_number(amount_trimmed)
            if parsed_amount <= 0:
                reject_reason = "NON_POSITIVE"

        # R4: BAD_CURRENCY
        if reject_reason is None:
            if pd.isna(currency):
                reject_reason = "BAD_CURRENCY"
            else:
                currency_upper = currency.strip().upper() if isinstance(currency, str) else str(currency).upper()
                if currency_upper not in ["USD", "EUR", "GBP"]:
                    reject_reason = "BAD_CURRENCY"

        # R5: BAD_DATE
        if reject_reason is None:
            if pd.isna(pay_date_txt):
                reject_reason = "BAD_DATE"
            else:
                pay_date_trimmed = pay_date_txt.strip() if isinstance(pay_date_txt, str) else str(pay_date_txt)
                if not is_valid_date(pay_date_trimmed):
                    reject_reason = "BAD_DATE"

        if reject_reason is not None:
            rejects.append({"row_num": row_num, "reject_reason": reject_reason})
        else:
            valid_rows.append({
                "row_num": row_num,
                "payment_id": payment_id.strip() if isinstance(payment_id, str) else payment_id,
                "account_id": account_id,
                "amount_txt": amount_txt,
                "currency": currency,
                "pay_date_txt": pay_date_txt
            })

    # R6: DUPLICATE - among rows that passed R1-R5
    if valid_rows:
        valid_df = pd.DataFrame(valid_rows)
        # Group by trimmed payment_id and find the minimum row_num in each group
        grouped = valid_df.groupby("payment_id")["row_num"].min()
        # Keep only rows where row_num is the minimum in their group
        valid_df["is_duplicate"] = ~valid_df.apply(
            lambda x: x["row_num"] == grouped[x["payment_id"]], axis=1
        )
        duplicates = valid_df[valid_df["is_duplicate"]]
        for _, dup_row in duplicates.iterrows():
            rejects.append({"row_num": dup_row["row_num"], "reject_reason": "DUPLICATE"})

        valid_df = valid_df[~valid_df["is_duplicate"]]
    else:
        valid_df = pd.DataFrame(columns=["row_num", "payment_id", "account_id", "amount_txt", "currency", "pay_date_txt"])

    # Build valid_payments output
    if len(valid_df) > 0:
        valid_payments = pd.DataFrame()
        valid_payments["payment_id"] = valid_df["payment_id"]
        valid_payments["account_id"] = valid_df["account_id"]
        valid_payments["amount"] = valid_df["amount_txt"].apply(lambda x: parse_legacy_number(x.strip()))
        valid_payments["currency"] = valid_df["currency"].apply(lambda x: x.strip().upper())
        valid_payments["pay_date"] = valid_df["pay_date_txt"].apply(lambda x: x.strip())
    else:
        valid_payments = pd.DataFrame(columns=["payment_id", "account_id", "amount", "currency", "pay_date"])

    # Build payment_rejects output
    if rejects:
        payment_rejects = pd.DataFrame(rejects)
    else:
        payment_rejects = pd.DataFrame(columns=["row_num", "reject_reason"])

    return {
        "valid_payments": valid_payments,
        "payment_rejects": payment_rejects
    }

def is_legacy_number(s: str) -> bool:
    """Check if string matches legacy number format: optional sign, digits, optional decimal with 1-2 digits."""
    pattern = r'^[+\-]?\d+(\.\d{1,2})?$'
    return bool(re.match(pattern, s))

def parse_legacy_number(s: str) -> float:
    """Parse legacy number string to float."""
    return float(s)

def is_valid_date(s: str) -> bool:
    """Check if string is exactly YYYY-MM-DD and a valid calendar date."""
    if not isinstance(s, str) or len(s) != 10:
        return False
    pattern = r'^\d{4}-\d{2}-\d{2}$'
    if not re.match(pattern, s):
        return False
    try:
        datetime.strptime(s, "%Y-%m-%d")
        return True
    except ValueError:
        return False
